package com.rpb.reservation.workforce.leave.entitlement;
import static com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementDtos.*;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;import com.rpb.reservation.workforce.attendance.daily.AttendanceDailyService;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.math.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class LeaveEntitlementService {
 private final WorkforceAccess gate;private final WorkforceEmployeeRepository employees;private final LeaveEntitlementRepository repository;private final AttendanceDailyService daily;private final WorkforceAudit audit;
 public LeaveEntitlementService(WorkforceAccess gate,WorkforceEmployeeRepository employees,LeaveEntitlementRepository repository,AttendanceDailyService daily,WorkforceAudit audit){this(gate,employees,repository,daily,audit,null,null,null);}
 @org.springframework.beans.factory.annotation.Autowired
 public LeaveEntitlementService(WorkforceAccess gate,WorkforceEmployeeRepository employees,LeaveEntitlementRepository repository,AttendanceDailyService daily,WorkforceAudit audit,com.rpb.reservation.workforce.compliance.ComplianceRepository contracts,com.rpb.reservation.workforce.leave.account.LeaveAccountRepository accounts,com.rpb.reservation.workforce.leave.account.LeaveBalanceEngine engine){this.contracts=contracts;this.accounts=accounts;this.engine=engine;this.gate=gate;this.employees=employees;this.repository=repository;this.daily=daily;this.audit=audit;}
 private final com.rpb.reservation.workforce.compliance.ComplianceRepository contracts;
 private final com.rpb.reservation.workforce.leave.account.LeaveAccountRepository accounts;
 private final com.rpb.reservation.workforce.leave.account.LeaveBalanceEngine engine;
 private boolean canonical(UUID tenant,UUID employee,UUID company,int year){return contracts!=null&&contracts.contracts(tenant,employee).stream().anyMatch(c->c.companyId().equals(company)&&!c.effectiveFrom().isAfter(LocalDate.of(year,12,31)));}
 private WorkforceDtos.Employee employee(CurrentActor actor,UUID store,UUID id,boolean write){gate.enter(actor,store);var e=id==null?employees.byAccount(actor.tenantId(),actor.actorId()).orElseThrow(WorkforceException::forbidden):employees.find(actor.tenantId(),id).orElseThrow(WorkforceException::missing);if(!e.storeIds().contains(store))throw WorkforceException.forbidden();if(write||!actor.actorId().equals(e.accountId())){gate.manage(actor,store);if(!gate.managedStores(actor).containsAll(e.storeIds()))throw WorkforceException.forbidden();}return e;}
 private void year(Integer year){if(year==null||year<1900||year>9998)throw WorkforceException.invalid();}
 public Page page(CurrentActor actor,UUID store,UUID employeeId,int year,UUID companyId){year(year);var e=employee(actor,store,employeeId,false);var company=companyId==null?repository.company(actor.tenantId(),store):companyId;if(!company.equals(repository.company(actor.tenantId(),store))||!repository.employed(actor.tenantId(),e.id(),company,year))throw WorkforceException.forbidden();var events=repository.events(actor.tenantId(),company,e.id(),year);var result=new ArrayList<Balance>();for(var type:repository.types(actor.tenantId(),company)){var p=repository.latest(actor.tenantId(),e.id(),company,type.id(),year).orElse(null);result.add(canonical(actor.tenantId(),e.id(),company,year)?canonicalBalance(actor.tenantId(),company,e.id(),year,type):balance(actor.tenantId(),company,e.id(),type,p,events.stream().filter(v->v.typeId().equals(type.id())).toList()));}return new Page(e.id(),year,gate.managedStores(actor).containsAll(e.storeIds()),result);}
 @Transactional public Policy save(CurrentActor actor,UUID store,UUID employee,UUID command,Write c){gate.sourceWrite(actor);employee(actor,store,employee,true);if(command==null||c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.companyId()==null||c.typeId()==null||c.reason()==null||c.reason().isBlank()||c.reason().length()>500||!Set.of("HOURS","DAYS").contains(c.unit()==null?"":c.unit()))throw WorkforceException.invalid();year(c.year());for(var n:Arrays.asList(c.grant(),c.carryIn(),c.adjustment()))if(n==null||n.scale()>6||n.precision()-n.scale()>12)throw WorkforceException.invalid();if(c.grant().signum()<0||c.carryIn().signum()<0||("DAYS".equals(c.unit())&&c.dayMinutes()==null)||(c.dayMinutes()!=null&&(c.dayMinutes()<1||c.dayMinutes()>1440)))throw WorkforceException.invalid();employees.lock(employee);employee(actor,store,employee,true);if(!repository.company(actor.tenantId(),store).equals(c.companyId())||!repository.typeInStore(actor.tenantId(),store,c.typeId())||!repository.employed(actor.tenantId(),employee,c.companyId(),c.year()))throw WorkforceException.invalid();var replay=repository.replay(actor.tenantId(),command,store,employee,actor.actorId(),c);if(replay.isPresent())return replay.get();if(canonical(actor.tenantId(),employee,c.companyId(),c.year()))throw new WorkforceException("LEAVE_CANONICAL_ACCOUNT_REQUIRED",409);var old=repository.latest(actor.tenantId(),employee,c.companyId(),c.typeId(),c.year()).orElse(null);if(c.expectedVersion()!=(old==null?0:old.version()))throw WorkforceException.conflict();var next=new Policy(command,c.companyId(),employee,c.typeId(),c.year(),c.grant(),c.carryIn(),c.adjustment(),c.unit(),c.dayMinutes(),c.reason(),c.expectedVersion()+1);var candidate=balance(actor.tenantId(),c.companyId(),employee,new Type(c.typeId(),"",store),next,repository.events(actor.tenantId(),c.companyId(),employee,c.year()).stream().filter(e->e.typeId().equals(c.typeId())).toList());if(candidate.remaining()==null)throw new WorkforceException("LEAVE_UNIT_POLICY_REQUIRED",409);if(candidate.remaining().signum()<0)throw new WorkforceException("LEAVE_BALANCE_INSUFFICIENT",409);repository.insert(actor.tenantId(),store,actor.actorId(),next);repository.receipt(actor.tenantId(),store,employee,actor.actorId(),command,c,next);audit.changed(actor,store,"leave-entitlement.grant",command,old,next);return next;}

 private Balance canonicalBalance(UUID tenant,UUID company,UUID employee,int year,Type type){
  var reasons=new ArrayList<String>();reasons.add("CANONICAL_LEAVE_ACCOUNT");
  var binding=accounts.bindings(tenant,type.storeId()).stream().filter(b->b.typeId().equals(type.id())).findFirst().orElse(null);
  var account=binding==null?null:accounts.accounts(tenant,employee,year).stream().filter(a->a.companyId().equals(company)&&a.kind().equals(binding.kind())).findFirst().orElse(null);
  if(account==null){reasons.add(binding==null?"LEAVE_TYPE_POLICY_REQUIRED":"LEAVE_ACCOUNT_REQUIRED");return new Balance(type.id(),type.name(),type.storeId(),company,null,"UNKNOWN",null,null,null,null,null,List.copyOf(reasons),null);}
  var b=engine.balance(tenant,account);reasons.addAll(b.issues());
  return new Balance(type.id(),type.name(),type.storeId(),company,null,b.issues().isEmpty()?"KNOWN":"UNKNOWN",null,null,b.used(),b.reserved(),b.available(),List.copyOf(reasons),account.unit().equals("hour")?"HOURS":"DAYS");
 }
 /** Called under the employee lock, before inserting either kind of leave request. */
 public void validateReservation(UUID tenant,UUID company,UUID employee,UUID type,LocalDate date,UUID source,Instant start,Instant end){
  var policy=repository.latest(tenant,employee,company,type,date.getYear()).orElse(null);
  if(policy==null)return; // No manual policy is an explicit unknown, never an invented entitlement.
  var events=new ArrayList<>(repository.events(tenant,company,employee,date.getYear()).stream().filter(e->e.typeId().equals(type)&&!e.id().equals(source)).toList());
  events.add(new Event(source,type,date,start,end,"pending"));
  var result=balance(tenant,company,employee,new Type(type,"",null),policy,events);
  if(result.remaining()==null)throw new WorkforceException("LEAVE_UNIT_POLICY_REQUIRED",409);
  if(result.remaining().signum()<0)throw new WorkforceException("LEAVE_BALANCE_INSUFFICIENT",409);
 }
 private record Window(LocalDate date,Instant start,Instant end,boolean approved){}
 private Balance balance(UUID tenant,UUID company,UUID employee,Type type,Policy policy,List<Event> events){
  var issues=new LinkedHashSet<String>();if(policy==null)issues.add("POLICY_MISSING");
  // Partition the union of requests at every boundary: approved wins over reserved.
  // This also deduplicates legacy/new requests and requests repeated across stores.
  var points=new TreeSet<Instant>();for(var e:events){points.add(e.start());points.add(e.end());}var boundaries=new ArrayList<>(points);long used=0,reserved=0;boolean measurable=true;var windows=new ArrayList<Window>();
  for(int i=0;i+1<boundaries.size();i++){var a=boundaries.get(i);var b=boundaries.get(i+1);var active=events.stream().filter(e->e.start().isBefore(b)&&e.end().isAfter(a)).toList();if(active.isEmpty())continue;boolean approved=active.stream().anyMatch(e->!e.status().equals("pending"));var selected=active.stream().filter(e->approved?!e.status().equals("pending"):true).toList();var dates=selected.stream().map(Event::workDate).distinct().toList();if(dates.size()!=1){issues.add("OVERLAPPING_WORK_DATES");measurable=false;continue;}if(!windows.isEmpty()){var previous=windows.getLast();if(previous.approved()==approved&&previous.date().equals(dates.getFirst())&&previous.end().equals(a)){windows.set(windows.size()-1,new Window(previous.date(),previous.start(),b,approved));continue;}}windows.add(new Window(dates.getFirst(),a,b,approved));}
  for(var window:windows){Long seconds=daily.measurableLeaveSeconds(tenant,company,employee,window.date(),window.start(),window.end());if(seconds==null){issues.add("ARRANGEMENT_OR_BREAK_UNKNOWN");measurable=false;}else if(window.approved())used+=seconds;else reserved+=seconds;}
  BigDecimal u=null,r=null,remaining=null;if(policy!=null&&measurable){var divisor=BigDecimal.valueOf(policy.unit().equals("HOURS")?3600L:policy.dayMinutes()*60L);u=BigDecimal.valueOf(used).divide(divisor,6,RoundingMode.HALF_UP);r=BigDecimal.valueOf(reserved).divide(divisor,6,RoundingMode.HALF_UP);remaining=policy.grant().add(policy.carryIn()).add(policy.adjustment()).subtract(BigDecimal.valueOf(used+reserved).divide(divisor,6,RoundingMode.HALF_UP));}
  return new Balance(type.id(),type.name(),type.storeId(),company,policy,issues.isEmpty()?"KNOWN":"UNKNOWN",measurable?used:null,measurable?reserved:null,u,r,remaining,List.copyOf(issues));
 }
}
